class HallucinationDetector:
    def __init__(self, context: Dict[str, Any]) -> None:
        super().__init__(
            context,
            stats_dependencies=[
                "sequence_logprobs",
            ],
            level="sequence",
        )

    def __call__(self, stats: Dict[str, np.ndarray]) -> np.ndarray:
        """
        Detects hallucinations by measuring the mean per-token negative log-probability.
        Hypothesis: Hallucinated sequences exhibit higher average surprise (lower probability) 
        per token compared to grounded sequences, independent of sequence length.
        """
        n_samples = len(stats["sequence_logprobs"])
        scores = np.zeros(n_samples, dtype=np.float32)

        for i, logprobs in enumerate(stats["sequence_logprobs"]):
            logprobs = np.asarray(logprobs, dtype=np.float32)
            if logprobs.size == 0:
                scores[i] = 0.0
            else:
                scores[i] = -np.mean(logprobs)

        return scores
